changeSet.sql:
ALTER TABLE activity_chat_messages ADD COLUMN channel varchar(32);
UPDATE activity_chat_messages SET channel = CASE WHEN activite_id IS NULL THEN 'COMMUNICATION' ELSE 'ACTIVITY' END;
ALTER TABLE activity_chat_messages ALTER COLUMN channel SET NOT NULL;
ALTER TABLE activity_chat_messages ADD CONSTRAINT ck_activity_chat_channel
  CHECK (channel IN ('ACTIVITY', 'COMMUNICATION', 'REFERENT_ENCADRANT'));
CREATE INDEX idx_activity_chat_channel_id ON activity_chat_messages (channel, id);
CREATE TABLE referent_encadrant_chat_reads (
  user_id bigint PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  last_message_id bigint NOT NULL
);

rollback.sql:
DROP TABLE referent_encadrant_chat_reads;
DROP INDEX idx_activity_chat_channel_id;
ALTER TABLE activity_chat_messages DROP CONSTRAINT ck_activity_chat_channel;
ALTER TABLE activity_chat_messages DROP COLUMN channel;
